<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Booking status</title><style>body{font-family:system-ui,sans-serif;background:#f5f5f2;color:#17211b}main{max-width:760px;margin:auto;padding:40px 20px}.card{background:#fff;border:1px solid #cad5ce;border-radius:14px;padding:24px}</style></head><body><main><div class="card"><h1>Booking confirmed</h1><p>{{ $booking->event_date }} · {{ ucfirst($booking->program) }} · {{ $booking->guests }} guests</p><p>Total: {{ number_format($booking->total_minor) }} {{ $booking->currency_code }} minor units</p><p>Verified deposit: {{ number_format($booking->deposit_minor) }} {{ $booking->currency_code }} minor units</p><p>Customer: {{ $booking->customer_name }}</p><p>Status: confirmed</p></div></main></body></html>